{
  "a_sentences": [
    {
      "a_text": "La question litigieuse porte sur la qualification, par la juridiction cantonale, des paiements effectués par l'assureur à ses cocontractantes comme salaires bruts soumis aux primes.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le Tribunal fédéral rappelle que le concept d'assuré au sens de la LAA et de l'OLAA, ainsi que les principes jurisprudentiels relatifs aux sous-traitants et à l'interprétation des formes juridiques, s'appliquent.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Il précise que les organes de l'AVS et de l'assurance-accidents ne sont pas tenus de reconnaître la forme juridique choisie si celle-ci apparaît inhabituelle et contraire au but, constituant un abus de droit.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Il retient également qu'une telle construction juridique ne doit pas être protégée si elle vise à éluder l'obligation de cotiser.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "La juridiction cantonale n'avait pas à examiner si l'assureur avait une obligation de contrôle spécifique des donneurs d'ouvrage.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que l'appréciation des preuves par la juridiction cantonale n'est pas critiquable.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Il juge que la prise en compte intégrale des paiements comme salaires soumis aux primes par l'assureur n'est pas à critiquer.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral estime que la juridiction cantonale pouvait à juste titre renoncer à des mesures d'instruction supplémentaires et à des auditions, aucune information décisive n'étant attendue.",
      "b_propositions": ["P8"]
    }
  ]
}
